description:
The `Sale` record is defined for you. Write `final class Report` with:

- `static TreeMap<String, Double> totalByRegion(List<Sale> sales)`: the total value (`qty * price`) per region;
- `static TreeMap<String, String> bestProduct(List<Sale> sales)`: for each region, the product with the highest total value there (ties: alphabetically first product);
- `static Map<Boolean, List<Integer>> bigAndSmall(List<Sale> sales, double limit)`: the sale ids whose value is at least `limit` under `true`, the rest under `false`, in their original order;
- `static String valueRange(List<Sale> sales)`: `"min..max"` of the sale values with one decimal, using `Collectors.teeing`, or `"none"` for no sales.

starter.Report.java:
import java.util.*;

public final class Report {
    public static TreeMap<String, Double> totalByRegion(List<Sale> sales) {
        return new TreeMap<>();
    }

    public static TreeMap<String, String> bestProduct(List<Sale> sales) {
        return new TreeMap<>();
    }

    public static Map<Boolean, List<Integer>> bigAndSmall(List<Sale> sales, double limit) {
        return new HashMap<>();
    }

    public static String valueRange(List<Sale> sales) {
        return "none";
    }
}

solution.Report.java:
import java.util.*;
import java.util.stream.*;

public final class Report {
    public static TreeMap<String, Double> totalByRegion(List<Sale> sales) {
        return sales.stream().collect(Collectors.groupingBy(Sale::region, TreeMap::new, Collectors.summingDouble(Sale::value)));
    }

    public static TreeMap<String, String> bestProduct(List<Sale> sales) {
        Comparator<Map.Entry<String, Double>> byTotal = (x, y) -> Double.compare(x.getValue(), y.getValue());
        TreeMap<String, String> out = new TreeMap<>();
        sales.stream()
                .collect(Collectors.groupingBy(Sale::region, Collectors.groupingBy(Sale::product, TreeMap::new, Collectors.summingDouble(Sale::value))))
                .forEach((region, byProduct) -> out.put(region, byProduct.entrySet().stream()
                        .max(byTotal.thenComparing(Map.Entry::getKey, Comparator.reverseOrder()))
                        .orElseThrow().getKey()));
        return out;
    }

    public static Map<Boolean, List<Integer>> bigAndSmall(List<Sale> sales, double limit) {
        return sales.stream().collect(Collectors.partitioningBy(s -> s.value() >= limit, Collectors.mapping(Sale::id, Collectors.toList())));
    }

    public static String valueRange(List<Sale> sales) {
        if (sales.isEmpty()) return "none";
        return sales.stream().map(Sale::value).collect(Collectors.teeing(
                Collectors.minBy(Double::compare),
                Collectors.maxBy(Double::compare),
                (min, max) -> String.format(Locale.ROOT, "%.1f..%.1f", min.orElseThrow(), max.orElseThrow())));
    }
}

unitTests:
List<Sale> sales = List.of(
        new Sale(1, "North", "tea", 3, 2.5), new Sale(2, "South", "tea", 1, 2.5),
        new Sale(3, "North", "cake", 2, 4.0), new Sale(4, "North", "tea", 4, 2.5),
        new Sale(5, "South", "coffee", 5, 3.0), new Sale(6, "South", "cake", 3, 5.0));

test("totals by region", () -> {
    checkEq(Report.totalByRegion(sales).toString(), "{North=25.5, South=32.5}");
});

test("best product per region, ties alphabetically", () -> {
    checkEq(Report.bestProduct(sales).toString(), "{North=tea, South=cake}");
    List<Sale> tie = List.of(new Sale(1, "X", "plum", 1, 2.0), new Sale(2, "X", "apple", 2, 1.0));
    checkEq(Report.bestProduct(tie).toString(), "{X=apple}");
});

test("partition by value", () -> {
    var p = Report.bigAndSmall(sales, 10);
    checkEq(p.get(true), List.of(4, 5, 6));
    checkEq(p.get(false), List.of(1, 2, 3));
});

test("value range", () -> {
    checkEq(Report.valueRange(sales), "2.5..15.0");
    checkEq(Report.valueRange(List.of()), "none");
});

